#!/usr/bin/env bash
set -Eeuo pipefail
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"
[[ -f .env ]] || { echo 'Missing .env. Run npm start once to initialize secrets.' >&2; exit 2; }
set -a
# .env is generated by Nexora bootstrap and contains shell-safe generated secrets.
. ./.env
set +a
: "${NEXORA_BACKUP_ENCRYPTION_KEY:?Backup encryption key missing from .env}"
mkdir -p backups
chmod 700 backups
STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
RAW="backups/.nexora-manual-$STAMP.dump.tmp"
ENC="backups/nexora-postgres-manual-$STAMP.dump.enc"
trap 'rm -f "$RAW"' EXIT

docker compose exec -T db sh -lc 'pg_dump -U "$POSTGRES_USER" -d "$POSTGRES_DB" -Fc' > "$RAW"
test -s "$RAW"
openssl enc -aes-256-cbc -salt -pbkdf2 -iter 200000 -pass env:NEXORA_BACKUP_ENCRYPTION_KEY -in "$RAW" -out "$ENC"
HMAC_KEY_OUTPUT="$(printf '%s' 'nexora-cloud-backup-hmac-v1' | openssl dgst -sha256 -hmac "$NEXORA_BACKUP_ENCRYPTION_KEY")"
HMAC_KEY="${HMAC_KEY_OUTPUT##*= }"
MAC_OUTPUT="$(openssl dgst -sha256 -mac HMAC -macopt "hexkey:$HMAC_KEY" "$ENC")"
printf '%s\n' "${MAC_OUTPUT##*= }" > "$ENC.hmac"
chmod 600 "$ENC" "$ENC.hmac"
echo "Encrypted manual backup created: $ENC"
echo 'Copy the .enc, .hmac, and encryption key (separately) to a second physical device.'
